<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?><header class="page-head"><p class="eyebrow">Tenant routing</p><h1>School domains</h1><p>Domain assignment is platform-controlled. Tenant administrators can verify the active configuration here.</p></header><section class="panel"><?php if($domains===[]):?><div class="empty">No hostname is assigned. Contact the platform administrator.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Hostname</th><th>Type</th><th>Status</th><th>Primary</th></tr></thead><tbody><?php foreach($domains as $domain):?><tr><td><?= esc($domain['domain']) ?></td><td><?= esc(str_replace('_',' ',$domain['type'])) ?></td><td><span class="badge"><?= esc($domain['status']) ?></span></td><td><?= $domain['is_primary']?'Yes':'No' ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section><?= $this->endSection() ?>
